// The one place the frontend gets data from.
//
// When NEXT_PUBLIC_API_URL is set, this posts to `${NEXT_PUBLIC_API_URL}/api/check`
// (docs/API.md). When it is not set, it returns docs/mock-response.json
// (copied to lib/generated by scripts/sync-mock.mjs before dev and build).
// The browser never calls ElevenLabs, Jev or Claude: only our own backend.

import mockResponse from "./generated/mock-response.json"
import type { ApiErrorBody, CheckResponse } from "./types"

export interface CheckRequest {
  /** "What they said" documents: txt, pdf. Sent as `claims_files`. */
  claimsFiles: File[]
  /** "What they said" audio: mp3, wav, m4a. Sent as `claims_audio`. */
  claimsAudio: File[]
  /** "The proof": txt, pdf, csv. Sent as `proof_files`. */
  proofFiles: File[]
  /** Optional pasted claims. Sent as `claims_text`. */
  claimsText?: string
  /** Optional stock ticker. Sent as `ticker`. */
  ticker?: string
  signal?: AbortSignal
}

export class ApiError extends Error {
  readonly status: number | null

  constructor(message: string, status: number | null = null) {
    super(message)
    this.name = "ApiError"
    this.status = status
  }
}

const API_URL = process.env.NEXT_PUBLIC_API_URL?.trim().replace(/\/+$/, "") ?? ""

/** True when no backend is configured and the starter case is served instead. */
export const isSampleMode = API_URL === ""

/** How long the sample case pretends to work, so the progress steps can be seen. */
const SAMPLE_DELAY_MS = 4200

export async function checkClaims(request: CheckRequest): Promise<CheckResponse> {
  if (isSampleMode) {
    await wait(SAMPLE_DELAY_MS, request.signal)
    return structuredClone(mockResponse) as CheckResponse
  }

  const form = new FormData()
  for (const file of request.claimsFiles) form.append("claims_files", file)
  for (const file of request.claimsAudio) form.append("claims_audio", file)
  for (const file of request.proofFiles) form.append("proof_files", file)
  if (request.claimsText?.trim()) form.append("claims_text", request.claimsText.trim())
  if (request.ticker?.trim()) form.append("ticker", request.ticker.trim())

  let response: Response
  try {
    response = await fetch(`${API_URL}/api/check`, {
      method: "POST",
      body: form,
      signal: request.signal,
    })
  } catch (error) {
    if (isAbort(error)) throw error
    throw new ApiError(
      "Could not reach the Diligo.ai server. Check your connection and try again."
    )
  }

  if (!response.ok) {
    const body = await readJson<ApiErrorBody>(response)
    const fallback =
      response.status >= 500
        ? "The server failed while checking the claims. Try again in a moment."
        : "The server could not read these files. Check them and try again."
    throw new ApiError(body?.error || fallback, response.status)
  }

  const body = await readJson<CheckResponse>(response)
  if (!body || !Array.isArray(body.findings)) {
    throw new ApiError("The server sent a response this screen cannot read. Try again, and report it if it repeats.", response.status)
  }
  return body
}

export interface Clip {
  /** An object URL for the audio. The caller must revoke it with URL.revokeObjectURL. */
  url: string
  /** "whole-file": the backend sent the whole recording, so the player must seek and stop itself. */
  mode: "segment" | "whole-file"
}

/** GET /api/clip for one audio finding (docs/API.md). Throws ApiError when it is not available. */
export async function fetchClip(
  audioFileId: string,
  startMs: number,
  endMs: number,
  signal?: AbortSignal
): Promise<Clip> {
  if (isSampleMode) throw new ApiError("No API URL is set, so there is no audio to play.")

  const query = new URLSearchParams({
    file: audioFileId,
    start_ms: String(startMs),
    end_ms: String(endMs),
  })

  let response: Response
  try {
    response = await fetch(`${API_URL}/api/clip?${query}`, { signal })
  } catch (error) {
    if (isAbort(error)) throw error
    throw new ApiError("Could not reach the Diligo.ai server.")
  }
  if (!response.ok) throw new ApiError("The audio clip is not available.", response.status)

  const mode = response.headers.get("X-Clip-Mode") === "whole-file" ? "whole-file" : "segment"
  const blob = await response.blob()
  return { url: URL.createObjectURL(blob), mode }
}

export function isAbort(error: unknown): boolean {
  return error instanceof DOMException && error.name === "AbortError"
}

async function readJson<T>(response: Response): Promise<T | null> {
  try {
    return (await response.json()) as T
  } catch {
    return null
  }
}

function wait(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException("Aborted", "AbortError"))
      return
    }
    const timer = setTimeout(resolve, ms)
    signal?.addEventListener(
      "abort",
      () => {
        clearTimeout(timer)
        reject(new DOMException("Aborted", "AbortError"))
      },
      { once: true }
    )
  })
}
